-- محتوای نمایشی «توس تعمیر» (دیتابیس تست) — در نصب واقعی اجرا نشود مگر برای محیط دمو
-- محصولات، مقالات و ویژگی‌های فنی نمونه؛ کاملاً تفکیک‌شده از seed اصلی.

CREATE TABLE IF NOT EXISTS product_features (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id INT UNSIGNED NOT NULL,
  feature_name VARCHAR(190) NOT NULL,
  feature_value VARCHAR(500) NOT NULL,
  sort_order SMALLINT NOT NULL DEFAULT 0,
  KEY pf_prod (product_id),
  CONSTRAINT pf_fk FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_persian_ci;


SELECT id, CONCAT('/assets/img/placeholder/product-', slug, '.svg'), alt_text, 0 FROM products WHERE slug IN ('pomp-takhlie-lbashooyi-bosh','floter-makhzan-ab-yakhchal-lg','bord-control-pakij-ebn-barat','motor-jarubarghi-tefal','heater-mikroove-panasonic','pomp-circulation-pakij','navar-darzgir-darb-lbashooyi-snowa','sensor-feshar-yakhchal-samsung','sabad-zarfshooyi-bala-electrolux','adapter-taghzie-12v-lavazem-shakhsi');

SELECT p.id,'برند دستگاه سازگار',b.name,0 FROM products p JOIN brands b ON b.id=p.brand_id;
SELECT p.id,'وضعیت موجودی',CASE WHEN p.stock_quantity>0 THEN 'موجود' ELSE 'ناموجود' END,1 FROM products p;
SELECT p.id,'وزن',CONCAT(p.weight,' گرم'),2 FROM products p WHERE p.weight IS NOT NULL AND p.weight>0;
SELECT p.id,'ابعاد',p.dimensions,3 FROM products p WHERE p.dimensions IS NOT NULL AND p.dimensions<>'';

