(1,1,'پمپ تخلیه لباسشویی بوش','pomp-takhlie-lbashooyi-bosh','TT-PMP-001','WMR-1500','پمپ تخلیه اصلی لباسشویی بوش، مناسب مدل‌های سری Maxx.','<p>پمپ تخلیه اورجینال مخصوص ماشین لباسشویی بوش. این قطعه وظیفه تخلیه آب از دیگ را بر عهده دارد و در صورت خرابی، دستگاه روی حالت خطای تخلیه می‌رود.</p><ul><li>ولتاژ کاری: ۲۲۰ ولت</li><li>جنس پروانه: برنج</li><li>گارانتی سلامت فیزیکی هنگام ارسال</li></ul>',1850000,1650000,12,'in_stock',450,'18×12×10 سانتی‌متر','Bosch Maxx 4/5/6, WLF20029',1,'قیمت پمپ تخلیه لباسشویی بوش | توس تعمیر','خرید پمپ تخلیه اصلی لباسشویی بوش با ارسال سریع به سراسر کشور. ضمانت اصالت قطعه.','پمپ تخلیه لباسشویی بوش','Product','index,follow'),
(3,2,'فلوتر مخزن آب یخچال ال جی','floter-makhzan-ab-yakhchal-lg','TT-FLT-002','QD-3300','فلوتر (شناور) قطع‌کن آب مخزن یخچال ساید ال‌جی.','<p>فلوتر مخزن آب برای قطع خودکار ورودی آب پس از پر شدن مخزن. سازگار با یخچال‌های ساید بای ساید ال‌جی.</p>',420000,NULL,30,'in_stock',60,'8×5×4 سانتی‌متر','LG Side by Side GR-B207, GR-J13',1,'فلوتر مخزن آب یخچال ال جی - خرید آنلاین','قیمت و خرید فلوتر مخزن آب یخچال ال‌جی اصل با گارانتی بازگشت وجه.','فلوتر مخزن آب یخچال ال جی','Product','index,follow'),
(4,10,'برد الکترونیکی کنترل پکیج ایران‌رادیاتور','bord-control-pakij-ebn-barat','TT-PCB-003','EL-7742','برد فرمان پکیج ترکیبی ایران‌رادیاتور؛ تعمیر و فروش با تست عملکرد.','<p>برد اصلی کنترل پکیج دیواری. امکان تعمیر برد معیوب شما نیز وجود دارد. قبل از ارسال، تمام توابع روی تست‌بنچ بررسی می‌شود.</p>',4200000,3850000,3,'low',780,'22×15×6 سانتی‌متر','Iran-Radiator BJV 24, BSI 28',1,'قیمت برد کنترل پکیج ایران‌رادیاتور | تعمیر برد پکیج مشهد','فروش و تعمیر برد الکترونیکی پکیج ایران‌رادیاتور با تست تخصصی در کارگاه توس تعمیر مشهد.','برد کنترل پکیج ایران رادیاتور','Product','index,follow'),
(6,12,'موتور جاروبرقی تفال','motor-jarubarghi-tefal','TT-MTR-004','VN-1200','موتور universal جاروبرقی تفال ۱۲۰۰ وات.','<p>موتور اصلی جاروبرقی تفال با توان نامی ۱۲۰۰ وات و بلبرینگ‌های صنعتی.</p>',1250000,NULL,8,'in_stock',900,'16×12×12 سانتی‌متر','Tefal TW series, Type R',1,'قیمت موتور جاروبرقی تفال','خرید موتور اصلی جاروبرقی تفال ۱۲۰۰ وات با ارسال سریع.','موتور جاروبرقی تفال','Product','index,follow'),
(5,13,'هیتر المویی مایکروویو پاناسونیک','heater-mikroove-panasonic','TT-HT-005','HP-2200','المان حرارتی (گریل) مایکروویو پاناسونیک ۲۲۰ ولت.','<p>المان حرارتی گریل مایکروویو؛ مناسب مدل‌های NN-GF و NN-CD.</p>',690000,590000,0,'out_of_stock',210,'24×8×3 سانتی‌متر','Panasonic NN-GF574, NN-CD878',1,'قیمت هیتر المویی مایکروویو پاناسونیک','خرید المان حرارتی گریل مایکروویو پاناسونیک اصل.','هیتر مایکروویو پاناسونیک','Product','index,follow'),
(4,10,'پمپ سیرکولاتور پکیج','pomp-circulation-pakij','TT-CIRC-006','CIR-2513','پمپ گردش آب گرم پکیج ۲۵/۱۳ با بدنه برنج.','<p>پمپ سیرکولاتور پکیج؛ سه دور سرعت، مناسب پکیج‌های ایرانی و خارجی.</p>',2750000,NULL,5,'in_stock',1500,'15×12×12 سانتی‌متر','پکیج‌های ۲۴ و ۲۸ هزار',1,'قیمت پمپ سیرکولاتور پکیج','پمپ circulation پکیج با بدنه برنج و سه دور سرعت؛ ارسال به سراسر کشور.','پمپ سیرکولاتور پکیج','Product','index,follow'),
(1,4,'نوار درزگیر درب لباسشویی اسنوا','navar-darzgir-darb-lbashooyi-snowa','TT-SEAL-007','DR-5060','لاستیک دور درب لباسشویی اسنوا قطر ۵۰ سانتی‌متر.','<p>نوار درزگیر لاستیکی درب ماشین لباسشویی اسنوا؛ ضد چکه و مقاوم در برابر مواد شوینده.</p>',780000,690000,18,'in_stock',350,'قطر ۵۰ سانتی‌متر','Snowa SWD-6063, SWD-7123',1,'قیمت نوار درزگیر درب لباسشویی اسنوا','خرید لاستیک دور درب لباسشویی اسنوا اصلی با ضمانت.','نوار درزگیر لباسشویی اسنوا','Product','index,follow'),
(3,3,'سنسور فشار کمپرسور یخچال سامسونگ','sensor-feshar-yakhchal-samsung','TT-SENS-008','SP-0910','سوئیچ فشار مدار گاز یخچال ساید سامسونگ.','<p>Pressure Switch مدار گاز یخچال ساید بای ساید سامسونگ.</p>',520000,NULL,25,'in_stock',80,'7×5×5 سانتی‌متر','Samsung RF series, RSA1',1,'قیمت سنسور فشار یخچال سامسونگ','خرید سنسور فشار کمپرسور یخچال سامسونگ اصل.','سنسور فشار یخچال سامسونگ','Product','index,follow'),
(2,6,'سبد ظرفشویی طبقه بالا الکترولوکس','sabad-zarfshooyi-bala-electrolux','TT-BASK-009','DK-2200','سبد (بازکت) طبقه بالایی ماشین ظرفشویی الکترولوکس.','<p>سبد قابل تنظیم ارتفاع ظرفشویی؛ شامل ریل و غلتک.</p>',1450000,NULL,6,'in_stock',1200,'50×35×20 سانتی‌متر','Electrolux ESL series',1,'قیمت سبد ظرفشویی الکترولوکس','خرید سبد طبقه بالای ظرفشویی الکترولوکس اصلی.','سبد ظرفشویی الکترولوکس','Product','index,follow'),
(8,14,'آداپتور تغذیه ۱۲ ولت لوازم شخصی برقی','adapter-taghzie-12v-lavazem-shakhsi','TT-ACC-010','AD-1202','آداپتور ۱۲ ولت ۲ آمپر برای لوازم شخصی برقی.','<p>آداپتور با فیش استاندارد، خروجی پایدار و محافظ اتصال کوتاه؛ مناسب ریش‌تراش، مسواک برقی و...</p>',260000,220000,40,'in_stock',120,'9×5×4 سانتی‌متر','شارژرهای ۱۲ ولتی عمومی',1,'آداپتور ۱۲ ولت لوازم شخصی برقی | توس تعمیر','خرید آداپتور ۱۲ ولت ۲ آمپر با کیفیت برای لوازم شخصی برقی.','آداپتور ۱۲ ولت','Product','index,follow');
