INSERT INTO articles (category_id,user_id,title,slug,excerpt,body,status,publish_at,views_count,seo_title,seo_description,focus_keyword,schema_type,ai_generated) VALUES
(1,NULL,'راهنمای عیب‌یابی لباسشویی: ۷ مشکل رایج و راه‌حل آن‌ها','rahenamayad-ebyabi-lbashooyi','از نچرخیدن دیگ تا صدای غیرعادی؛ علائم خرابی لباسشویی را بشناسید و قبل از تماس با تعمیرکار، موارد ساده را بررسی کنید.','<p>لباسشویی یکی از پرکارترین لوازم خانگی است و خرابی‌های آن اغلب با علائم مشخصی همراه است. در این مقاله هفت مشکل رایج را معرفی می‌کنیم.</p><h2>۱. لباسشویی روشن نمی‌شود</h2><p>ابتدا پریز، فیوز و قفل درب را بررسی کنید. اگر چراغ پنل روشن می‌شود اما دستگاه شروع به کار نمی‌کند، احتمال خرابی برد یا قفل درب وجود دارد.</p><h2>۲. آب تخلیه نمی‌شود</h2><p>گرفتگی فیلتر پمپ، خمیدگی شلنگ تخلیه یا خرابی خود پمپ شایع‌ترین دلایل هستند.</p><h2>۳. صدای غیرعادی هنگام خشک کردن</h2><p>بلبرینگ دیگ یا ضربه‌گیرها معمولاً متهم ردیف اول‌اند. ادامه کار با این صدا می‌تواند به دیگ آسیب بزند.</p><p>در بسیاری موارد، تشخیص دقیق نیاز به حضور تکنسین دارد. تیم توس تعمیر در مشهد با عیب‌یابی در محل، هزینه شما را کاهش می‌دهد.</p>','published',NOW(),23,'عیب‌یابی لباسشویی در مشهد | توس تعمیر','راهنمای عملی شناسایی ۷ مشکل رایج لباسشویی؛ چه زمانی خودتان بررسی کنیم و چه زمانی با تعمیرکار تماس بگیریم.','عیب یابی لباسشویی در مشهد','Article',0),
(1,NULL,'چه زمانی باید برد الکترونیکی لوازم خانگی را تعمیر کنیم؟','keyan-bord-lavamzesh-ra-tamir-konim','نشانه‌هایی که می‌گوید مشکل از برد است نه قطعه مصرفی؛ راهنمای تصمیم‌گیری بین تعمیر و تعویض برد.','<p>برد الکترونیکی مغز متفکر لوازم خانگی است. خرابی آن اغلب با علائم مبهم خود را نشان می‌دهد.</p><h2>علائم خرابی برد</h2><ul><li>خطای پیوسته نمایشگر بدون دلیل منطقی</li><li>روشن نشدن کامل دستگاه در حالی که برق ورودی سالم است</li><li>عملکرد نامنظم پمپ یا المنت</li></ul><h2>تعمیر یا تعویض؟</h2><p>در بیشتر بردها، خرابی محدود به یک یا چند قطعه (خازن، رله، TRIAC) است و تعمیر آن بسیار ارزان‌تر از تعویض برد کامل تمام می‌شود. کارگاه تخصصی برد توس تعمیر با تست بنچ، گزارش وضعیت قطعات ارائه می‌دهد.</p>','published',NOW(),41,'تعمیر برد الکترونیکی در مشهد | توس تعمیر','تشخیص خرابی برد لوازم خانگی و مقایسه هزینه تعمیر و تعویض برد؛ راهنمای تخصصی توس تعمیر مشهد.','تعمیر برد الکترونیکی مشهد','Article',0),
(2,NULL,'نکات نگهداری یخچال ساید بای ساید برای افزایش عمر دستگاه','negahdari-yakhchal-side-by-side','با چند عادت ساده، مصرف انرژی و استهلاک یخچال ساید خود را تا سال‌ها کاهش دهید.','<p>یخچال‌های ساید بای ساید به دلیل پیچیدگی بیشتر، به نگهداری منظم نیاز دارند.</p><h2>فیلتر آب را جدی بگیرید</h2><p>تعویض به‌موقع فیلتر آب هم طعم آب را تضمین می‌کند هم از یخ‌ساز محافظت می‌کند.</p><h2>کندانسور تمیز</h2><p>گردوغبار پشت یا زیر دستگاه باعث کارکرد طولانی کمپرسور و افزایش مصرف برق می‌شود؛ هر شش ماه یک‌بار آن را تمیز کنید.</p><p>اگر یخچال شما بیش از حد کار می‌کند یا دما نوسان دارد، پیش از خرابی کامل با تعمیرکار متخصص مشورت کنید.</p>','published',NOW(),17,'نگهداری یخچال ساید بای ساید | توس تعمیر','آموزش نگهداری یخچال ساید بای ساید: فیلتر آب، کندانسور، لاستیک درب و نکات کاهش مصرف انرژی.','نگهداری یخچال در مشهد','Article',0),
(1,NULL,'قیمت تعمیر پکیج در مشهد؛ چه عواملی هزینه را تعیین می‌کنند؟','gheimat-tamir-pakij-mashhad','اجزای هزینه تعمیر پکیج: نوع خرابی، قطعه یدکی و دستمزد تخصصی؛ شفاف و واقعی.','<p>هزینه تعمیر پکیج به چند عامل بستگی دارد: خرابی قطعه مصرفی مانند سنسور یا پمپ، یا ایراد در مبدل و مشعل که کار سنگین‌تری می‌طلبد.</p><h2>عیب‌یابی درست، هزینه کمتر</h2><p>متأسفانه گاهی به‌جای عیب‌یابی دقیق، چند قطعه به‌صورت آزمون و خطا تعویض می‌شود. روش توس تعمیر، تست مرحله‌به‌مرحله با تجهیزات اندازه‌گیری و اعلام هزینه شفاف پیش از شروع کار است.</p>','published',NOW(),34,'هزینه تعمیر پکیج در مشهد | توس تعمیر','عوامل تعیین قیمت تعمیر پکیج دیواری در مشهد؛ عیب‌یابی تخصصی و اعلام هزینه شفاف پیش از کار.','تعمیر پکیج در مشهد','Article',0);
